package br.com.onda;
import java.net.*;
import java.util.*;
import java.util.regex.*;
/** Public video links and direct media files; a sharing caption may contain exactly one URL. */
final class MediaLinks {
 static String resolve(String input){try{if(input==null||input.length()>4096)throw new Exception();String text=input.trim(),value=text;if(!text.matches("https://\\S+")){Matcher m=Pattern.compile("https://[^\\s<>\"']+").matcher(text);if(!m.find())throw new Exception();value=m.group().replaceFirst("[).,;!]+$","");if(m.find())throw new Exception();}URI uri=new URI(value);try{return DownloadLinks.resolve(value);}catch(IllegalArgumentException ignored){}if(!publicShape(uri))throw new Exception();if(tiktokHost(uri.getHost()))return tiktok(value);if(!extension(value).isEmpty())return uri.toASCIIString();throw new Exception();}catch(Exception e){throw new IllegalArgumentException("Cole um link HTTPS de vídeo/playlist do YouTube, vídeo do TikTok ou arquivo MP4, MP3 ou M4A.");}}
 static boolean publicShape(URI u){String h=u.getHost();if(!"https".equalsIgnoreCase(u.getScheme())||h==null||u.getUserInfo()!=null||u.getPort()!=-1||u.getFragment()!=null)return false;h=h.toLowerCase(Locale.ROOT);if(h.indexOf(':')>=0||!h.contains(".")||h.endsWith(".")||h.endsWith(".local")||h.endsWith(".localhost")||h.endsWith(".internal")||h.endsWith(".lan")||h.endsWith(".test")||h.endsWith(".invalid"))return false;if(h.matches("[0-9.]+"))return false;return true;}
 static boolean tiktokHost(String host){if(host==null)return false;return Arrays.asList("tiktok.com","www.tiktok.com","m.tiktok.com","vt.tiktok.com","vm.tiktok.com").contains(host.toLowerCase(Locale.ROOT));}
 static boolean isTikTok(String url){try{return tiktokHost(new URI(url).getHost());}catch(Exception e){return false;}}
 static String tiktok(String input)throws Exception{URI uri=new URI(input);if(!publicShape(uri)||!tiktokHost(uri.getHost()))throw new Exception();String host=uri.getHost().toLowerCase(Locale.ROOT),path=uri.getPath();if(host.equals("vt.tiktok.com")||host.equals("vm.tiktok.com")){if(!path.matches("/[A-Za-z0-9]{5,100}/?"))throw new Exception();return "https://"+host+path;}if(path.matches("/t/[A-Za-z0-9]{5,100}/?"))return "https://www.tiktok.com"+path;if(path.matches("/@[\\p{L}\\p{N}_.-]+/video/[0-9]{10,24}/?")||path.matches("/share/video/[0-9]{10,24}/?")||path.matches("/embed/(v2/)?[0-9]{10,24}/?"))return new URI("https","www.tiktok.com",path,null).toASCIIString();throw new Exception();}
 static String videoId(String url){try{Matcher m=Pattern.compile("/(?:video|embed|embed/v2)/([0-9]{10,24})(?:/|$)").matcher(new URI(url).getPath());return m.find()?m.group(1):"";}catch(Exception e){return "";}}
 static String extension(String url){try{String path=new URI(url).getPath().toLowerCase(Locale.ROOT);for(String extension:new String[]{"mp4","mp3","m4a"})if(path.endsWith("."+extension))return extension;}catch(Exception ignored){}return "";}
 static String source(String url){if(isTikTok(url))return "TikTok";return extension(url).isEmpty()?"YouTube":"arquivo direto";}
}
